/* ---------- Donut chart ---------- */
/* where the agent's time went this week, as a gauge (owner, 21 Nov): a half ring of parts in the
   chart palette's saturated colours, in order, with small gaps and slightly rounded corners, and the rest of the week's budget
   as a light grey track. The total sits in the middle with what it is out of, and the legend under the gauge names each part
   with a bar of its colour and its hours. Pointing at a part or a row, or the keyboard on a row, lights both and puts that part
   in the middle; a click on either (or Enter on a row) selects it, so it stays in the middle with its row filled until it is
   clicked again or Escape clears it. A quiet head: the title with a hairline under it. The content sits 16px in from every
   edge; each row's mark and hours sit on the content's edges, its hover a quiet fill that reaches out round them */
.dnx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);--dm-dnx-track:var(--dm-chip);--dm-dnx-th:18;--dm-dnx-cr:4}
.dnx-h{padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:17px;color:var(--dm-fg)}
.dnx-g{position:relative;width:220px;max-width:100%;margin:var(--dm-s-1) auto 0}
.dnx-svg{display:block;width:100%;height:auto;overflow:visible}
.dnx-svg path{stroke-linejoin:round;transition:opacity var(--dm-t-fast) var(--dm-ease);cursor:default}
/* (a page that draws its own parts gives them their own stroke-width) */
.dnx-svg path:not([stroke-width]){stroke-width:calc(var(--dm-dnx-cr) * 2px)}
.dnx-svg .tr{fill:var(--dm-dnx-track);stroke:var(--dm-dnx-track);cursor:auto}
.dnx-g.hov path:not(.hl,.tr){opacity:.3}
.dnx-c{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;pointer-events:none}
.dnx-c b{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.01em;color:var(--dm-fg)}
.dnx-c span{font-size:12px;line-height:16px}
/* the last row's words end 16px from the card's foot, its hover fill reaching out round them */
.dnx-lg{position:relative;display:flex;flex-direction:column;gap:2px;margin:0 calc(-1 * var(--dm-s-2)) calc(-1 * var(--dm-s-2))}
.dnx-r{position:relative;display:flex;align-items:center;gap:var(--dm-s-2);width:100%;padding:6px var(--dm-s-2);border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;line-height:20px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.dnx-r.hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dnx-r:hover{background:var(--dm-row)}}
.dnx-r.sel{background:color-mix(in srgb,var(--dm-fg) 9%,transparent)}
.dnx-r.sel .t{color:var(--dm-fg)}
.dnx-svg path[data-i]{cursor:pointer}
/* the hover that glides from row to row is Clean's (below); the other styles fill the row itself */
.dnx-hv{display:none}
.dnx-r:focus-visible{outline-offset:-2px}
.dnx-r i{width:3px;height:14px;border-radius:2px;flex:none}
.dnx-r .t{flex:1;min-width:0;color:var(--dm-fg2)}
.dnx-r .v{color:var(--dm-fg)}
/* Blueprint: square corners on the parts and the track */
:root:not([data-style="soft"],[data-style="clean"]) .dnx-svg path:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){stroke-linejoin:miter}
/* Clean (owner, 21 Nov: "it definitely has to be updated"): the title on an off-white head strip that follows the card's
   corners; a slimmer ring (14px against Soft's 18) with a little rounder corners (5px against 4); the track recessed with
   Clean's inner shadow (an SVG filter, since a path takes no inset box-shadow); the legend
   Clean's 10px rows with its one hover, a neutral fill that eases in over 220ms and glides from row to
   row (it only fades with reduced motion), and the selected row a stronger fill of the same shape. The middle's figure is set
   with tabular figures and Clean's tighter tracking. In Clean dark the accent is white (owner, 21 Nov; Clean dark's tokens),
   so the first part is white; the other parts keep the palette's hues */
:root[data-style="clean"] .dnx,:root [data-style="clean"] .dnx,:root [data-style="clean"].dnx{--dm-dnx-th:14;--dm-dnx-cr:5}
:root[data-style="clean"] .dnx-h,:root [data-style="clean"] .dnx-h,:root [data-style="clean"].dnx-h{margin:calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4)) 0;padding:calc(var(--dm-strip-y) + 4px) var(--dm-s-4);background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0;font-size:13px;line-height:20px;font-weight:500}
:root[data-style="clean"] .dnx-svg .tr,:root [data-style="clean"] .dnx-svg .tr,:root [data-style="clean"].dnx-svg .tr{filter:var(--dm-dnx-in)}
:root[data-style="clean"] .dnx-svg .dnx-in-s,:root [data-style="clean"] .dnx-svg .dnx-in-s,:root [data-style="clean"].dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.12)}
:root[data-style="clean"] .dnx-svg .dnx-in-r,:root [data-style="clean"] .dnx-svg .dnx-in-r,:root [data-style="clean"].dnx-svg .dnx-in-r{flood-color:rgba(0,0,0,.04)}
:root[data-style="clean"] .dnx-c b,:root [data-style="clean"] .dnx-c b,:root [data-style="clean"].dnx-c b{letter-spacing:-.02em;font-variant-numeric:tabular-nums}
:root[data-style="clean"] .dnx-c span,:root [data-style="clean"] .dnx-c span,:root [data-style="clean"].dnx-c span{color:var(--dm-muted);letter-spacing:0}
:root[data-style="clean"] .dnx-r,:root [data-style="clean"] .dnx-r,:root [data-style="clean"].dnx-r{border-radius:var(--dm-r-in)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dnx-lg.gl .dnx-r:is(:hover,.hl),:root [data-style="clean"] .dnx-lg.gl .dnx-r:is(:hover,.hl),:root [data-style="clean"].dnx-lg.gl .dnx-r:is(:hover,.hl){background:transparent}}
:root[data-style="clean"] .dnx-r.sel,:root [data-style="clean"] .dnx-r.sel,:root [data-style="clean"].dnx-r.sel,:root[data-style="clean"] .dnx-lg.gl .dnx-r.sel,:root [data-style="clean"] .dnx-lg.gl .dnx-r.sel,:root [data-style="clean"].dnx-lg.gl .dnx-r.sel{background:color-mix(in srgb,var(--dm-fg) 11%,var(--dm-surface))}
:root[data-style="clean"] .dnx-hv,:root [data-style="clean"] .dnx-hv,:root [data-style="clean"].dnx-hv{display:block;position:absolute;left:0;right:0;top:0;height:32px;border-radius:var(--dm-r-in);background:var(--dm-hover);opacity:0;pointer-events:none;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t-fast) var(--dm-ease),height var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"][data-theme="dark"] .dnx-svg .dnx-in-s,:root[data-theme="dark"] [data-style="clean"] .dnx-svg .dnx-in-s,:root[data-theme="dark"] [data-style="clean"].dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.5)}
:root[data-style="clean"][data-theme="dark"] .dnx-svg .dnx-in-r,:root[data-theme="dark"] [data-style="clean"] .dnx-svg .dnx-in-r,:root[data-theme="dark"] [data-style="clean"].dnx-svg .dnx-in-r{flood-color:rgba(255,255,255,.05)}
@media (prefers-color-scheme:dark){
  :root[data-style="clean"]:not([data-theme="light"]) .dnx-svg .dnx-in-s,:root:not([data-theme="light"]) [data-style="clean"] .dnx-svg .dnx-in-s,:root:not([data-theme="light"]) [data-style="clean"].dnx-svg .dnx-in-s{flood-color:rgba(0,0,0,.5)}
  :root[data-style="clean"]:not([data-theme="light"]) .dnx-svg .dnx-in-r,:root:not([data-theme="light"]) [data-style="clean"] .dnx-svg .dnx-in-r,:root:not([data-theme="light"]) [data-style="clean"].dnx-svg .dnx-in-r{flood-color:rgba(255,255,255,.05)}}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .dnx-hv,:root [data-style="clean"] .dnx-hv,:root [data-style="clean"].dnx-hv{transition:opacity var(--dm-t-fast) var(--dm-ease)}}

DM.def('donut-chart', (r, c) => {
  // the week's agent hours by kind of task, out of a 40-hour budget
  const D = [['Design reviews', 14.2, 'var(--dm-c1)'], ['Code changes', 9.6, 'var(--dm-c2)'], ['Research', 6.1, 'var(--dm-c3)'], ['Copy edits', 5.1, 'var(--dm-c4)']], MAX = 40, OF = 'of 40h this week';
  const tot = D.reduce((a, d) => a + d[1], 0);
  const svg = $('.dnx-svg', r), lg = $('.dnx-lg', r), g = $('.dnx-g', r), v = $('.dnx-v', r), l = $('.dnx-l', r), uid = 'dnx' + Math.random().toString(36).slice(2, 8);
  /* the half ring: centred on the middle of its base, the parts 4px apart. Its thickness and corner radius are the style's
     (--dnx-th, --dnx-cr: 18px and 4px, Clean 14px and 5px), read when it draws */
  const CX = 110, CY = 110, RO = 104, GAP = 4;
  let RI = 86, CR = 4;
  const geo = () => { const cs = getComputedStyle(svg); RI = RO - (parseFloat(cs.getPropertyValue('--dm-dnx-th')) || 18); CR = parseFloat(cs.getPropertyValue('--dm-dnx-cr')) || 4; };
  const P = (rho, a) => `${(CX + rho * Math.cos(a)).toFixed(2)} ${(CY - rho * Math.sin(a)).toFixed(2)}`;
  /* one part, from f0 to f1 of the sweep (left to right over the top). The corners are rounded by a stroke of their radius drawn
     round the part's shape inset by that radius, so the outline is the part's own and only its corners turn (Blueprint joins
     the stroke square, which gives the square part). gs and ge are the room left at each end: half the gap where it meets
     another part, nothing at the ring's own ends */
  const part = (f0, f1, gs, ge) => {
    const ts = Math.PI * (1 - f0), te = Math.PI * (1 - f1), ro = RO - CR, ri = RI + CR;
    let os = ts - Math.asin((gs + CR) / ro), oe = te + Math.asin((ge + CR) / ro), is = ts - Math.asin((gs + CR) / ri), ie = te + Math.asin((ge + CR) / ri);
    if (os < oe) os = oe = (os + oe) / 2;
    if (is < ie) is = ie = (is + ie) / 2;
    return `M${P(ro, os)}A${ro} ${ro} 0 0 1 ${P(ro, oe)}L${P(ri, ie)}A${ri} ${ri} 0 0 0 ${P(ri, is)}Z`;
  };
  const cum = []; let acc = 0; D.forEach(d => { cum.push([acc / MAX, (acc + d[1]) / MAX]); acc += d[1]; });
  /* Clean's inner shadow for the track (Clean's CSS turns it on through --dnx-in): a 1px ring just inside the edge and a soft
     shade from the top, each the track's own shape cut out of a blurred or shrunk copy of it */
  svg.style.setProperty('--dm-dnx-in', `url(#${uid}-in)`);
  svg.innerHTML = `<defs><filter id="${uid}-in" filterUnits="userSpaceOnUse" x="-4" y="-4" width="228" height="118" color-interpolation-filters="sRGB">`
    + `<feOffset in="SourceAlpha" dy="1" result="o"/><feGaussianBlur in="o" stdDeviation="1.5" result="b"/><feComposite in="SourceAlpha" in2="b" operator="out" result="e"/>`
    + `<feFlood class="dnx-in-s"/><feComposite in2="e" operator="in" result="s"/>`
    + `<feMorphology in="SourceAlpha" operator="erode" radius="1" result="k"/><feComposite in="SourceAlpha" in2="k" operator="out" result="q"/>`
    + `<feFlood class="dnx-in-r"/><feComposite in2="q" operator="in" result="r"/>`
    + `<feMerge><feMergeNode in="SourceGraphic"/><feMergeNode in="s"/><feMergeNode in="r"/></feMerge></filter></defs>`
    + D.map((d, i) => `<path data-i="${i}" style="fill:${d[2]};stroke:${d[2]}"/>`).join('') + `<path class="tr"/>`;
  const arcs = $$('path[data-i]', svg), track = $('.tr', svg);
  // the parts sweep in to the front f, and the track fills what is left after it
  const draw = f => {
    geo();
    cum.forEach(([a, b], i) => { const e = Math.min(b, f); arcs[i].setAttribute('d', e > a + .004 ? part(a, e, a ? GAP / 2 : 0, e < 1 ? GAP / 2 : 0) : ''); });
    const end = Math.min(f, tot / MAX); track.setAttribute('d', end < .996 ? part(end, 1, end ? GAP / 2 : 0, 0) : '');
  };
  lg.innerHTML = `<i class="dnx-hv" aria-hidden="true"></i>` + D.map((d, i) => `<button type="button" class="dnx-r" data-i="${i}" aria-pressed="false"><i style="background:${d[2]}"></i><span class="t">${d[0]}</span><span class="v num">${d[1]}h</span></button>`).join('');
  lg.classList.add('gl');
  const rows = $$('.dnx-r', lg), hv = $('.dnx-hv', lg);
  /* what the middle shows: the part pointed at or focused, else the selected one, else the total. Clean's hover is one fill
     under the rows that glides to the row in question, appearing where it is the first time rather than sliding in */
  let hov = null, sel = null, swept = false, hvOn = false;
  const glide = i => {
    if (i == null){ hv.style.opacity = '0'; hvOn = false; return; }
    const y = rows[i].offsetTop, h = rows[i].offsetHeight;
    if (!hvOn){ hv.style.transition = 'none'; hv.style.transform = `translateY(${y}px)`; hv.style.height = h + 'px'; void hv.offsetWidth; hv.style.transition = ''; }
    else { hv.style.transform = `translateY(${y}px)`; hv.style.height = h + 'px'; }
    hv.style.opacity = '1'; hvOn = true;
  };
  const show = () => { const i = hov ?? sel; g.classList.toggle('hov', i != null);
    arcs.forEach((a, j) => a.classList.toggle('hl', j === i)); rows.forEach((x, j) => { x.classList.toggle('hl', j === i); x.classList.toggle('sel', j === sel); x.setAttribute('aria-pressed', String(j === sel)); });
    glide(hov);
    if (!swept) return;
    if (i == null){ v.textContent = tot.toFixed(1) + 'h'; l.textContent = OF; } else { v.textContent = D[i][1] + 'h'; l.textContent = D[i][0]; } };
  const pick = i => { sel = sel === i ? null : i; show(); };
  arcs.forEach(el => { el.onmouseenter = () => { hov = +el.dataset.i; show(); }; el.onmouseleave = () => { hov = null; show(); }; el.onclick = () => pick(+el.dataset.i); });
  // on the legend the pointer moving from row to row keeps the hover (the gap between rows included); it goes when it leaves
  rows.forEach(el => { el.onmouseenter = () => { hov = +el.dataset.i; show(); }; el.onclick = () => pick(+el.dataset.i);
    el.onfocus = () => { hov = +el.dataset.i; show(); }; el.onblur = e => { if (!rows.includes(e.relatedTarget)){ hov = null; show(); } };
    el.onkeydown = e => { if (e.key === 'Escape' && sel != null){ sel = null; show(); } }; });
  lg.onmouseleave = () => { const f = document.activeElement; if (!(lg.contains(f) && f.matches(':focus-visible'))){ hov = null; show(); } };
  stagger(rows, 60, 150);
  v.textContent = '0.0h'; l.textContent = OF; draw(0);
  // the parts sweep in once the gauge has risen into view, and the total counts up with them (a part pointed at meanwhile is
  // named in the middle once the count is done)
  c.later(260, () => tween(0, tot / MAX, REDUCE ? 1 : 1200, (f, p) => { draw(f); if (p >= 1){ swept = true; show(); } else v.textContent = (Math.min(f, tot / MAX) * MAX).toFixed(1) + 'h'; }, t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2));
});
